// This file is generated by AI.

const { spawn } = require('child_process');
const path = require('path');
const {
    createMessageConnection,
    StreamMessageReader,
    StreamMessageWriter,
} = require('vscode-jsonrpc/node');
const { PassThrough } = require('stream');

// 平台 -> 二进制文件名映射
const PLATFORM_BIN_MAP = {
    linux: 'webgal-language-server-linux-x86_64',
    darwin: 'webgal-language-server-macos-x86_64',
    win32: 'webgal-language-server-windows-x86_64.exe',
};

// macOS 下自动检测 Apple Silicon
if (process.platform === 'darwin' && process.arch === 'arm64') {
    PLATFORM_BIN_MAP.darwin = 'webgal-language-server-macos-aarch64';
}

module.exports = {
    name: 'WebGAL Language Server',

    async start() {
        const binName = PLATFORM_BIN_MAP[process.platform];
        if (!binName) {
            throw new Error(`Unsupported platform: ${process.platform}`);
        }

        const binPath = path.join(__dirname, 'bin', binName);
        console.log(`[Terre Adapter] Starting: ${binPath}`);

        // 启动语言服务器子进程
        this._proc = spawn(binPath, [], {
            stdio: ['pipe', 'pipe', 'pipe'],
            env: { ...process.env },
        });

        // 将子进程的 stderr 转发到当前进程的 stderr, 方便调试
        this._proc.stderr.pipe(process.stderr);
        this._proc.on('exit', code => console.log(`[Terre Adapter] Process exited (${code})`));
        this._proc.on('error', err => console.error(`[Terre Adapter] Process error:`, err));

        // 创建面向子进程的 MessageConnection
        const childReader = new StreamMessageReader(this._proc.stdout);
        const childWriter = new StreamMessageWriter(this._proc.stdin);
        this._childConnection = createMessageConnection(childReader, childWriter);

        // 创建面向 Terre 代理的流 (通过 PassThrough 实现)
        const toTerre = new PassThrough();
        const fromTerre = new PassThrough();
        const terreReader = new StreamMessageReader(fromTerre);
        const terreWriter = new StreamMessageWriter(toTerre);
        this._terreConnection = createMessageConnection(terreReader, terreWriter);

        // 返回给 Terre 的 reader / writer
        return {
            reader: new StreamMessageReader(fromTerre),
            writer: new StreamMessageWriter(toTerre),
        };
    },

    /**
     * 注册扩展协议, 注入宿主能力.
     * 这里会启动双向转发, 并拦截子进程发出的自定义请求, 由宿主直接处理.
     */
    registerExtensions(host) {
        const child = this._childConnection;
        const terre = this._terreConnection;

        // 1. 来自 Terre 客户端的请求 / 通知 -> 原样转发给子进程
        terre.onRequest((method, params, token) => {
            return child.sendRequest(method, params, token);
        });
        terre.onNotification((method, params) => {
            child.sendNotification(method, params);
        });

        // 2. 来自子进程的请求 / 通知 -> 先检查是否为需要宿主的自定义方法
        child.onRequest(async (method, params, token) => {
            switch (method) {
                case 'workspace/fs/readFile':
                    return await host.readFile(params.path);
                case 'workspace/fs/readDirectory':
                    return await host.readDirectory(params.path);
                case 'workspace/fs/exists':
                    return await host.stat(params.path);
                default:
                    // 其他请求转发给 Terre 代理 (最终到达 Monaco)
                    return terre.sendRequest(method, params, token);
            }
        });

        child.onNotification((method, params) => {
            // 所有通知都直接转发
            terre.sendNotification(method, params);
        });

        // 启动连接监听
        child.listen();
        terre.listen();

        console.log('[Terre Adapter] Extensions registered with host');
    },

    /**
     * 停止语言服务器并释放连接
     */
    async stop() {
        if (this._childConnection) {
            this._childConnection.dispose();
            this._childConnection = null;
        }
        if (this._terreConnection) {
            this._terreConnection.dispose();
            this._terreConnection = null;
        }
        if (this._proc) {
            this._proc.kill();
            this._proc = null;
        }
    },
};
